import{_ as e,C as n,c as i,o as r,j as t,G as a,a0 as l,b as s,a as o,w as u,a1 as h}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Sitzungsleitfaden: Einführung in das mentale Spiel (2-3 Stunden)","description":"","frontmatter":{},"headers":[],"relativePath":"de/mental-journey/session-guide.md","filePath":"de/mental-journey/session-guide.md"}');const g=e({name:"de/mental-journey/session-guide.md"},[["render",function(e,d,g,c,p,m){const b=n("AdBanner"),f=n("Mermaid"),k=n("AdInArticle");return r(),i("div",null,[d[1]||(d[1]=t("h1",{id:"sitzungsleitfaden-einfuhrung-in-das-mentale-spiel-2-3-stunden",tabindex:"-1"},[o("Sitzungsleitfaden: Einführung in das mentale Spiel (2-3 Stunden) "),t("a",{class:"header-anchor",href:"#sitzungsleitfaden-einfuhrung-in-das-mentale-spiel-2-3-stunden","aria-label":'Permalink to "Sitzungsleitfaden: Einführung in das mentale Spiel (2-3 Stunden)"'},"​")],-1)),a(b),d[2]||(d[2]=l('<h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>Dieser Leitfaden hilft Ihnen bei der Durchführung einer 2- bis 3-stündigen Einführung in das Mentaltraining für Pétanque-Spieler. Ideal für Trainer, Vereinsverantwortliche oder erfahrene Spieler, die Mentaltraining in ihr Team integrieren möchten.</p><div class="tip custom-block"><p class="custom-block-title">Dieser Leitfaden enthält zwei Abschnitte.</p><ul><li><strong><a href="#for-participants">Für Teilnehmer</a></strong> – Was die Spieler lernen werden</li><li><strong><a href="#for-facilitators">Für Moderatoren</a></strong> – So führen Sie die Sitzung durch</li></ul></div><h2 id="schnellzugriff" tabindex="-1">Schnellzugriff <a class="header-anchor" href="#schnellzugriff" aria-label="Permalink to &quot;Schnellzugriff&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Abschnitt</th><th>Zweck</th><th>Zugang</th></tr></thead><tbody><tr><td><strong>Für Teilnehmer</strong></td><td>Was Sie von der Sitzung erwarten können</td><td><a href="#for-participants">Abschnitt anzeigen</a></td></tr><tr><td><strong>Für Moderatoren</strong></td><td>Vollständiger Sitzungsplan und Zeitplan</td><td><a href="#for-facilitators">Abschnitt anzeigen</a></td></tr><tr><td><strong>Sitzungsmaterialien</strong></td><td>Leitfäden, Folien und Arbeitsblätter</td><td><a href="/en/mental-journey/materials">Materialien ansehen</a></td></tr><tr><td><strong>Checkliste zur Vorbereitung</strong></td><td>Was Sie vor der Sitzung vorbereiten sollten</td><td><a href="#preparation-1-week-before">Checkliste ansehen</a></td></tr></tbody></table><hr><h2 id="fur-teilnehmer" tabindex="-1">Für Teilnehmer <a class="header-anchor" href="#fur-teilnehmer" aria-label="Permalink to &quot;Für Teilnehmer&quot;">​</a></h2><h3 id="was-sie-erwartet" tabindex="-1">Was Sie erwartet <a class="header-anchor" href="#was-sie-erwartet" aria-label="Permalink to &quot;Was Sie erwartet&quot;">​</a></h3><p>In dieser Session lernen Sie das mentale Spiel Pétanque anhand von Diskussionen, Übungen und praktischen Techniken kennen, die Sie sofort anwenden können.</p><p><strong>Sie werden lernen:</strong></p><ul><li>Warum mentales Training für die Leistung wichtig ist</li><li>Der Unterschied zwischen „technischem Modus“ und „Flow-Modus“</li><li>Wie Sie Ihren inneren Kritiker erkennen und mit ihm umgehen können</li><li>Einfache Techniken zur Druckbewältigung</li><li>Eine grundlegende Vorbereitungsroutine</li></ul><p><strong>Was Sie benötigen:</strong></p><ul><li>Offenheit und Bereitschaft zum Teilen</li><li>Notizbuch und Stift</li><li>Ihre eigenen Erfahrungen zum Besprechen</li><li>2-3 Stunden konzentrierte Zeit</li></ul><h3 id="sitzungsstruktur" tabindex="-1">Sitzungsstruktur <a class="header-anchor" href="#sitzungsstruktur" aria-label="Permalink to &quot;Sitzungsstruktur&quot;">​</a></h3>',14)),(r(),s(h,null,{default:u(()=>[a(f,{id:"mermaid-157",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BEinf%C3%BChrung%20%3Cbr%2F%3E%2020%20Minuten%5D%20--%3E%20B%5BDie%20Zone%20%3Cbr%2F%3E%2040%20Minuten%5D%0A%20%20%20%20B%20--%3E%20C%5BBrechen%20%3Cbr%2F%3E%2010%20Minuten%5D%0A%20%20%20%20C%20--%3E%20D%5BInnerer%20Kritiker%20%3Cbr%2F%3E%2040%20Minuten%5D%0A%20%20%20%20D%20--%3E%20E%5BPraktische%20Werkzeuge%20%3Cbr%2F%3E%2040%20Minuten%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegration%20%3Cbr%2F%3E%2020%20Minuten%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:u(()=>[...d[0]||(d[0]=[o(" Loading... ",-1)])]),_:1})),d[3]||(d[3]=l('<h3 id="wichtige-konzepte-die-sie-erkunden-werden" tabindex="-1">Wichtige Konzepte, die Sie erkunden werden <a class="header-anchor" href="#wichtige-konzepte-die-sie-erkunden-werden" aria-label="Permalink to &quot;Wichtige Konzepte, die Sie erkunden werden&quot;">​</a></h3><h4 id="_1-die-zone-stromungszustand" tabindex="-1">1. Die Zone (Strömungszustand) <a class="header-anchor" href="#_1-die-zone-stromungszustand" aria-label="Permalink to &quot;1. Die Zone (Strömungszustand)&quot;">​</a></h4><ul><li>Wie es sich anfühlt, wenn alles zusammenpasst</li><li>Warum das Nachdenken über die Technik die Leistung beeinträchtigt</li><li>Der &quot;Wechsel&quot; von der Planung zur Ausführung</li></ul><h4 id="_2-der-innere-kritiker" tabindex="-1">2. Der innere Kritiker <a class="header-anchor" href="#_2-der-innere-kritiker" aria-label="Permalink to &quot;2. Der innere Kritiker&quot;">​</a></h4><ul><li>Wie sich negatives Selbstgespräch auf die Leistung auswirkt</li><li>Der Unterschied zwischen innerem Kritiker und innerem Coach</li><li>Neutrale Beobachtung vs. hartes Urteil</li></ul><h4 id="_3-druckreaktion" tabindex="-1">3. Druckreaktion <a class="header-anchor" href="#_3-druckreaktion" aria-label="Permalink to &quot;3. Druckreaktion&quot;">​</a></h4><ul><li>Warum du im Wettkampf anders spielst</li><li>Körperliche Anzeichen von Druck</li><li>Schnelle Reset-Techniken</li></ul><h4 id="_4-praktische-werkzeuge" tabindex="-1">4. Praktische Werkzeuge <a class="header-anchor" href="#_4-praktische-werkzeuge" aria-label="Permalink to &quot;4. Praktische Werkzeuge&quot;">​</a></h4><ul><li>3-Atemzug-Reset</li><li>Einfache Vorbereitungsroutine</li><li>Fehlerkorrekturprotokoll</li></ul><h3 id="was-sie-mitbringen-sollten" tabindex="-1">Was Sie mitbringen sollten <a class="header-anchor" href="#was-sie-mitbringen-sollten" aria-label="Permalink to &quot;Was Sie mitbringen sollten&quot;">​</a></h3><p><strong>Erforderlich:</strong></p><ul><li>Du selbst und deine Erfahrungen</li><li>Bereitschaft zur Teilnahme</li></ul><p><strong>Optional:</strong></p><ul><li>Beispiele für mentale Herausforderungen, denen Sie begegnen</li><li>Fragen zu konkreten Situationen</li><li>Notizbuch für persönliche Notizen</li></ul><h3 id="nach-der-sitzung" tabindex="-1">Nach der Sitzung <a class="header-anchor" href="#nach-der-sitzung" aria-label="Permalink to &quot;Nach der Sitzung&quot;">​</a></h3><p>Sie erhalten:</p><ul><li>Zusammenfassung der wichtigsten Konzepte</li><li>Übungsaufgaben für die Woche</li><li>Links zu detaillierten Schulungsmodulen</li><li>Zielvorlage für die mentale Spielentwicklung</li></ul>',17)),a(k),d[4]||(d[4]=l('<hr><h2 id="fur-moderatoren" tabindex="-1">Für Moderatoren <a class="header-anchor" href="#fur-moderatoren" aria-label="Permalink to &quot;Für Moderatoren&quot;">​</a></h2><h3 id="vorbereitungs-checkliste" tabindex="-1">Vorbereitungs-Checkliste <a class="header-anchor" href="#vorbereitungs-checkliste" aria-label="Permalink to &quot;Vorbereitungs-Checkliste&quot;">​</a></h3><p><strong>1 Woche vorher:</strong></p><ul><li>[ ] Zimmer für 2-3 Stunden buchen</li><li>[ ] Laden Sie 6-12 Teilnehmer ein</li><li>[ ] Materialseiten als Lesezeichen speichern (siehe <a href="/en/mental-journey/materials">Materialien</a>)</li><li>[ ] Lesen Sie diese Anleitung sorgfältig durch.</li><li>[ ] Bereiten Sie ein Flipchart oder eine Whiteboard-Tafel vor.</li></ul><p><strong>1 Tag zuvor:</strong></p><ul><li>[ ] Teilnahme bestätigen</li><li>[ ] Raum einrichten (Kreisbestuhlung)</li><li>[ ] Jegliche Technologie (Folien usw.) testen.</li><li>[ ] Materialien vorbereiten</li></ul><p><strong>1 Stunde vorher:</strong></p><ul><li>[ ] Früh anreisen</li><li>[ ] Die Sitzplätze werden im Kreis angeordnet.</li><li>[ ] Einrichtungsmaterialien</li><li>[ ] Zentriere dich</li></ul><h3 id="ihre-rolle-als-moderator" tabindex="-1">Ihre Rolle als Moderator <a class="header-anchor" href="#ihre-rolle-als-moderator" aria-label="Permalink to &quot;Ihre Rolle als Moderator&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Sie sind <strong>kein</strong> Therapeut oder technischer Coach. Sie sind ein <strong>Moderator</strong>, der:</p><ul><li>Leitfäden Diskussion</li><li>Schafft einen sicheren Raum</li><li>Verbindet Konzepte mit Erfahrungen</li><li>Steuert die Gruppendynamik</li></ul></div><p><strong>Wichtigste Fähigkeiten:</strong></p><ul><li>Aktives Zuhören</li><li>Neutrale Präsenz</li><li>Umgang mit unterschiedlichen Persönlichkeiten</li><li>Zu wissen, wann man weiterziehen sollte</li></ul><h3 id="detaillierter-sitzungsplan" tabindex="-1">Detaillierter Sitzungsplan <a class="header-anchor" href="#detaillierter-sitzungsplan" aria-label="Permalink to &quot;Detaillierter Sitzungsplan&quot;">​</a></h3><hr><h4 id="teil-1-einfuhrung-20-minuten" tabindex="-1">Teil 1: Einführung (20 Minuten) <a class="header-anchor" href="#teil-1-einfuhrung-20-minuten" aria-label="Permalink to &quot;Teil 1: Einführung (20 Minuten)&quot;">​</a></h4><p><strong>Ziele:</strong></p><ul><li>Psychologische Sicherheit schaffen</li><li>Erwartungen festlegen</li><li>Gruppenverbindung aufbauen</li></ul><p><strong>Skript:</strong></p><p>„Herzlich willkommen! In dieser Session geht es um das mentale Spiel beim Pétanque – die Gedanken, Gefühle und Verhaltensmuster, die Ihre Leistung beeinflussen.“</p><p><strong>Grundregeln:</strong></p><ol><li>Was hier geteilt wird, bleibt hier.</li><li>Keine Wertung der Erfahrungen anderer</li><li>Die Teilnahme ist freiwillig.</li><li>Es gibt keine falschen Antworten.</li></ol><p><strong>Kurzrunde:</strong> Name, Spieldauer und eine mentale Herausforderung, der Sie sich stellen müssen.</p><p><strong>Hinweise für den Moderator:</strong></p><ul><li>Gehen Sie zunächst auf die Modellschwachstellen ein.</li><li>Die Vorstellungsrunden sollten kurz sein (jeweils 1 Minute).</li><li>Gemeinsame Themen erkennen</li><li>Alle Antworten prüfen</li></ul><hr><h4 id="teil-2-die-zone-der-flow-zustand-40-minuten" tabindex="-1">Teil 2: Die Zone / Der Flow-Zustand (40 Minuten) <a class="header-anchor" href="#teil-2-die-zone-der-flow-zustand-40-minuten" aria-label="Permalink to &quot;Teil 2: Die Zone / Der Flow-Zustand (40 Minuten)&quot;">​</a></h4><p><strong>Ziele:</strong></p><ul><li>Strömungszustände verstehen</li><li>Technischen Modus vs. Arbeitsablaufmodus erkennen</li><li>Lerne das &quot;Schalter&quot;-Konzept kennen.</li></ul><p><strong>Einstiegsfrage:</strong> „Denken Sie an eine Zeit, in der Sie Ihr bestes Boule-Spiel absolviert haben. Wie hat es sich angefühlt? Was war anders?“</p><p><strong>Diskussionsanregungen:</strong></p><ol><li>„Wie viele von euch haben schon mal ein Spiel erlebt, bei dem einfach alles perfekt geklappt hat?“</li><li>Woran haben Sie in diesen Momenten gedacht?</li><li>&quot;Worin unterscheidet sich das von Situationen, in denen man Schwierigkeiten hat?&quot;</li></ol><p><strong>Wichtigste Lerninhalte:</strong></p><p>Benutze das Whiteboard zum Zeichnen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Übung: Der Schalter (10 Minuten)</strong></p><p>„Lasst uns den Wechselmoment üben:</p><ol><li>Aufstehen</li><li>Stell dir vor, du befindest dich außerhalb des Kreises – denk an einen Schuss.</li><li>Atme tief durch</li><li>Schritt vorwärts (in einen imaginären Kreis)</li><li>Lass beim Gehen die Analyse los.</li><li>Konzentriere dich nur auf ein imaginäres Ziel.</li></ol><p><strong>Nachbesprechung:</strong></p><ul><li>&quot;Was ist Ihnen aufgefallen?&quot;</li><li>„War es leicht oder schwer, das Denken loszulassen?“</li><li>„Wie könnte sich das auf reale Spiele anwenden lassen?“</li></ul><hr><h4 id="teil-3-pause-10-minuten" tabindex="-1">Teil 3: Pause (10 Minuten) <a class="header-anchor" href="#teil-3-pause-10-minuten" aria-label="Permalink to &quot;Teil 3: Pause (10 Minuten)&quot;">​</a></h4><p><strong>Maßnahmen des Moderators:</strong></p><ul><li>Fördern Sie informelle Gespräche</li><li>Gruppenenergie beachten</li><li>Bereiten Sie sich auf den nächsten Abschnitt vor</li></ul><hr><h4 id="teil-4-der-innere-kritiker-40-minuten" tabindex="-1">Teil 4: Der innere Kritiker (40 Minuten) <a class="header-anchor" href="#teil-4-der-innere-kritiker-40-minuten" aria-label="Permalink to &quot;Teil 4: Der innere Kritiker (40 Minuten)&quot;">​</a></h4><p><strong>Ziele:</strong></p><ul><li>Negative Selbstgesprächsmuster erkennen</li><li>Unterscheide den inneren Kritiker vom inneren Coach</li><li>Üben Sie eine neutrale Beobachtung</li></ul><p><strong>Öffnung:</strong> „Wir alle haben eine innere Stimme, die unsere Leistung kommentiert. Manchmal ist sie hilfreich, manchmal harsch. Lasst uns das genauer betrachten.“</p><p><strong>Übung: Inventar des inneren Kritikers (15 Minuten)</strong></p><p>„Schreibe auf dein Blatt Papier:</p><ol><li>Was deine innere Stimme nach einem missglückten Wurf sagt</li><li>Was es aussagt, wenn man unter Druck steht</li><li>Was es über Ihre Fähigkeiten aussagt</li></ol><p><em>Bitte geben Sie sich 5 Minuten Zeit zum Schreiben.</em></p><p>„Wer ist nun bereit, ein Beispiel zu nennen?“</p><p><strong>Hinweise für den Moderator:</strong></p><ul><li>Normalisiere harte Selbstgespräche</li><li>Versuche nicht, jemanden zu &quot;reparieren&quot;.</li><li>Achten Sie auf wiederkehrende Muster</li></ul><p><strong>Unterrichtsmethode: Innerer Kritiker vs. Innerer Coach (15 Minuten)</strong></p><p>Zeichne zwei Spalten auf die Tafel:</p><table tabindex="0"><thead><tr><th>Innerer Kritiker</th><th>Inner Coach</th></tr></thead><tbody><tr><td>&quot;Wie konnte man das übersehen?!&quot;</td><td>&quot;Das ging nach links.&quot;</td></tr><tr><td>&quot;Du versagst immer.&quot;</td><td>&quot;Versuchen wir es noch einmal.&quot;</td></tr><tr><td>&quot;Du bist schrecklich.&quot;</td><td>&quot;Was kann ich lernen?&quot;</td></tr></tbody></table><p><strong>Diskussion:</strong></p><ul><li>„Fällt Ihnen der Unterschied auf?“</li><li>Welche Stimme hilft bei der Performance?</li><li>„Kannst du die Stimme verändern?“</li></ul><p><strong>Übung: Reframing (10 Minuten)</strong></p><p>„Nehmen Sie eine Ihrer Aussagen des inneren Kritikers. Wie würde ein innerer Coach sie formulieren?“</p><p>Nennen Sie Beispiele.</p><hr><h4 id="teil-5-praktische-hilfsmittel-40-minuten" tabindex="-1">Teil 5: Praktische Hilfsmittel (40 Minuten) <a class="header-anchor" href="#teil-5-praktische-hilfsmittel-40-minuten" aria-label="Permalink to &quot;Teil 5: Praktische Hilfsmittel (40 Minuten)&quot;">​</a></h4><p><strong>Ziele:</strong></p><ul><li>Lerne die 3-Atemzug-Reset-Technik.</li><li>Erstelle eine einfache Vorbereitungsroutine.</li><li>Fehlerkorrektur verstehen</li></ul><p><strong>Werkzeug 1: 3-Atemzug-Reset (10 Minuten)</strong></p><p>„Das ist Ihr Notfall-Reset-Knopf. Benutzen Sie ihn, wenn Sie merken, dass der Druck steigt.“</p><p><strong>Zeigen:</strong></p><ol><li>Atmen Sie 4 Sekunden lang ein.</li><li>Halten Sie die Taste für 2 Sekunden gedrückt.</li><li>Atmen Sie 6 Sekunden lang aus.</li><li>3 Mal wiederholen</li></ol><p>„Lasst uns jetzt zusammen üben.“</p><p><em>Führe die Gruppe durch 3 Zyklen</em></p><p><strong>Nachbesprechung:</strong></p><ul><li>„Was haben Sie an Ihrem Körper bemerkt?“</li><li>Wann könnte man das verwenden?</li></ul><p><strong>Tool 2: Einfache Vorbereitungsroutine (15 Minuten)</strong></p><p>„Eine Routine hilft Ihnen dabei, konsequent von der Planung zur Ausführung überzugehen.“</p><p><strong>Grundstruktur:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Übung:</strong> „Erstelle deine eigene 3-Schritte-Routine. Schreib sie auf.“</p><p>Nennen Sie Beispiele.</p><p><strong>Werkzeug 3: Protokoll zur Fehlerbehebung (15 Minuten)</strong></p><p>„Spitzenspieler machen nicht weniger Fehler. Sie erholen sich schneller davon.“</p><p><strong>3-Schritte-Protokoll:</strong></p><ol><li><strong>Beobachten</strong> – Stellen Sie die Tatsache neutral dar („Das ging nach links“).</li><li><strong>Lernen</strong> – Informationen extrahieren („Der Wind ist stärker als ich dachte“)</li><li><strong>Zurücksetzen</strong> – Vorwärts bewegen (3-Atemzüge, Blick geradeaus)</li></ol><p><strong>Üben:</strong> „Denken Sie an einen Fehler, der Ihnen kürzlich unterlaufen ist. Gehen Sie die drei Schritte durch.“</p><hr><h4 id="teil-6-integration-amp-abschluss-20-minuten" tabindex="-1">Teil 6: Integration &amp; Abschluss (20 Minuten) <a class="header-anchor" href="#teil-6-integration-amp-abschluss-20-minuten" aria-label="Permalink to &quot;Teil 6: Integration &amp;amp; Abschluss (20 Minuten)&quot;">​</a></h4><p><strong>Ziele:</strong></p><ul><li>Gelerntes festigen</li><li>Aktionspläne erstellen</li><li>Ressourcen bereitstellen</li></ul><p><strong>Reflexionsfragen:</strong></p><ol><li>Welche Erkenntnis nehmen Sie mit?</li><li>&quot;Was ist eine Sache, die du diese Woche ausprobieren wirst?&quot;</li><li>Welche Fragen bleiben offen?</li></ol><p><strong>Aktionsplanung (10 Minuten)</strong></p><p>„Schreiben Sie auf Ihr Handout:</p><ol><li>Eine Technik, die Sie diese Woche üben werden</li><li>Wann und wo du es üben wirst</li><li>Wie Sie Ihren Fortschritt verfolgen werden</li></ol><p><strong>Ressourcen:</strong></p><ul><li>Zusammenfassungsblatt aushändigen</li><li>Webseite teilen: carreau.app</li><li>Empfohlenes Einstiegsmodul: <a href="/en/education/the-zone/">The Zone</a></li></ul><p><strong>Abschlussrunde:</strong> „Ein Wort, das beschreibt, wie du dich gerade fühlst.“</p><p><strong>Schlussworte:</strong> „Mentales Training ist eine Fähigkeit wie jede andere – es braucht Übung. Fangen Sie klein an, haben Sie Geduld mit sich selbst und beobachten Sie die Veränderungen. Vielen Dank für Ihre Offenheit heute.“</p><hr><h3 id="tipps-fur-moderatoren" tabindex="-1">Tipps für Moderatoren <a class="header-anchor" href="#tipps-fur-moderatoren" aria-label="Permalink to &quot;Tipps für Moderatoren&quot;">​</a></h3><h4 id="umgang-mit-schwierigen-situationen" tabindex="-1">Umgang mit schwierigen Situationen <a class="header-anchor" href="#umgang-mit-schwierigen-situationen" aria-label="Permalink to &quot;Umgang mit schwierigen Situationen&quot;">​</a></h4><p><strong>Wenn jemand dominiert:</strong></p><ul><li>„Vielen Dank, [Name]. Wir möchten nun auch die anderen hören.“</li><li>Nutzen Sie eine strukturierte Gesprächsführung.</li></ul><p><strong>Wenn sich jemand widersetzt:</strong></p><ul><li>Streitet euch nicht.</li><li>„Das ist eine berechtigte Ansicht. Was denken andere?“</li><li>Mit ihrem Anliegen übereinstimmen</li></ul><p><strong>Wenn jemand emotional wird:</strong></p><ul><li>Normalisiere es</li><li>„Das berührt etwas Reales. Danke fürs Teilen.“</li><li>Versuche nicht, es zu reparieren</li></ul><p><strong>Falls die Diskussion ins Stocken gerät:</strong></p><ul><li>Verwenden Sie spezifische Eingabeaufforderungen.</li><li>Teilen Sie Ihr eigenes Beispiel.</li><li>Wechseln Sie zu einer Übung</li></ul><h4 id="energiemanagement" tabindex="-1">Energiemanagement <a class="header-anchor" href="#energiemanagement" aria-label="Permalink to &quot;Energiemanagement&quot;">​</a></h4><p><strong>Hoher Energiebedarf:</strong> Nutzen Sie Übungen und Bewegung. <strong>Geringe Energie:</strong> Stellen Sie provokante Fragen <strong>Verstreut:</strong> Zurück zur Struktur bringen <strong>Zeitform:</strong> Humor einsetzen oder Pause</p><h3 id="nach-der-sitzung-1" tabindex="-1">Nach der Sitzung <a class="header-anchor" href="#nach-der-sitzung-1" aria-label="Permalink to &quot;Nach der Sitzung&quot;">​</a></h3><p><strong>Nachverfolgen:</strong></p><ul><li>Senden Sie innerhalb von 24 Stunden eine zusammenfassende E-Mail.</li><li>Fügen Sie Links zu Ressourcen hinzu.</li><li>Bieten Sie an, Fragen zu beantworten</li><li>Vereinbaren Sie einen optionalen Folgetermin</li></ul><p><strong>Selbstreflexion:</strong></p><ul><li>Was hat gut funktioniert?</li><li>Was würdest du ändern?</li><li>Was hat Sie überrascht?</li><li>Was hast du gelernt?</li></ul>',118)),a(b),d[5]||(d[5]=l('<hr><h2 id="materialien" tabindex="-1">Materialien <a class="header-anchor" href="#materialien" aria-label="Permalink to &quot;Materialien&quot;">​</a></h2><ul><li><a href="/en/mental-journey/materials#participant-guide">Teilnehmerleitfaden</a></li><li><a href="/en/mental-journey/materials#facilitator-slides">Folien für den Moderator</a></li><li><a href="/en/mental-journey/materials#summary-sheet">Zusammenfassungsblatt</a></li><li><a href="/en/mental-journey/materials#exercise-worksheets">Übungsblätter</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Bereit zur Moderation?</p><ol><li>Lesen Sie diese Anleitung sorgfältig durch.</li><li>Materialien herunterladen</li><li>Üben Sie die Übungen selbst</li><li>Vereinbaren Sie Ihren Termin</li><li>Vertraue dem Prozess</li></ol></div>',5))])}]]);export{d as __pageData,g as default};
